$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$required='index.html','shop.html','product.html','contact.html','about.html','appointment.html','privacy.html','terms.html','cookies.html','legal-notice.html','responsible-use.html','404.html','offline.html';$errors=@();foreach($name in $required){$path=Join-Path $root $name;if(-not(Test-Path $path)){$errors+="$name missing";continue};$html=Get-Content -Raw $path;if($html-notmatch'<title>.+</title>'){$errors+="$name title"};if($html-notmatch'<meta name="description"'){$errors+="$name description"};if($html-notmatch'<html lang='){$errors+="$name lang"};$ids=[regex]::Matches($html,'\bid="([^"]+)"')|ForEach-Object{$_.Groups[1].Value};$dupes=$ids|Group-Object|Where-Object Count -gt 1;if($dupes){$errors+="$name duplicate IDs"}};if($errors){throw($errors-join"`n")};'Required public pages and core metadata validated.'
